  Lemma main_regs_ok_d : regs_ok (ENV (vals0 sp0 a0s path envv rdraw tid regs0 inp)) sr_main regs0.
  Proof.
    pose proof (main_regs_ok sp0 a0s path envv uid hw rdraw tid regs0 mem0 Hva Hve Hvsp Htid inp mbase entry ME) as HR.
    eapply regs_ok_bagree; [apply ENV_agree | vm_compute; reflexivity | exact HR].
  Qed.

