  Proof.
    pose proof (main_know_ok sp0 a0s path envv uid hw rdraw tid regs0 mem0 Hva Hve Hvsp Htid inp mbase entry ME) as HK.
    eapply know_ok_bagree; [apply ENV_agree | vm_compute; reflexivity |].
    eapply ksubl_sound; [exact HK | exact kn_d0_sub].
  Qed.

  (* [comment removed for export] *)
  Definition open_err_k (KA : TSet) : Prop :=
    forall e vals R M,
      (1 <= e <= 4095)%Z ->
      length vals = 39%nat -> vals_ev vals 0 = sp0 -> vals_ev vals 38 = errno_ret e ->
      vals_ev vals 2 = p1 a0s path envv rdraw inp ->
      regs_ok (Env (vals_ev vals) (blobs_ev (blobs0 a0s path hw rdraw))) (sr_upd Ns0OpenFail_defs.srA (ridx 10) (EVar 38)) R ->
      know_ok RSEGS (Env (vals_ev vals) (blobs_ev (blobs0 a0s path hw rdraw))) M Ns0OpenFail_defs.knA ->
      above_sp0 M ->
      srealizes RSEGS scfg (mkCfg (mkst R (Z_to_bv 64 0xba924) M (seg_rom RSEGS)) model0) KA.

  #[using="Type"] Lemma ENV_agree_r : forall vals, blob_agree 4 (ENV vals) (Env (vals_ev vals) (blobs_ev (blobs0 a0s path hw rdraw))).
  Proof.
    intros vals. destruct (ENV_agree vals) as [A B]. split; [intros n; symmetry; apply A | intros k Hk; symmetry; apply B; exact Hk].
  Qed.

  Lemma main_kimg_alloc : know_ok RSEGS (ENV (vals0 sp0 a0s path envv rdraw tid regs0 inp)) mem0 [KImg 0xf8c58 0xfa000; KImg 0xc6dd1 0xd8780].
  Proof.
    pose proof (main_know_ok sp0 a0s path envv uid hw rdraw tid regs0 mem0 Hva Hve Hvsp Htid inp mbase entry ME) as HK.
    constructor; [|constructor; [|constructor]].
    - exact (know_nth RSEGS _ _ kn_main ltac:(let i := kidx kn_main (is_kimg_cov 0xf8c58 (0xfa000 - 0xf8c58)) in exact i) _ HK eq_refl).
    - exact (know_nth RSEGS _ _ kn_main ltac:(let i := kidx kn_main (is_kimg_cov 0xc6dd1 (0xd8780 - 0xc6dd1)) in exact i) _ HK eq_refl).
  Qed.

  (* [comment removed for export] *)
  Definition file_k (KF : TSet) : Prop :=
    forall vals R M VM (A1 : Z),
      length vals = 70%nat -> vals_ev vals 0 = sp0 -> vals_ev vals 48 = Z_to_bv 64 A1 ->
      vals_ev vals 1 = p0 a0s path envv rdraw inp -> vals_ev vals 2 = p1 a0s path envv rdraw inp ->
      vals_ev vals 3 = auxvp sp0 a0s path envv -> vals_ev vals 4 = rnd sp0 a0s path envv inp -> vals_ev vals 5 = tid ->
      regs_ok (ENV vals) srC0 R -> know_ok RSEGS (ENV vals) M knC0 ->
      above_sp0 M -> block_range L A1 65536 ->
      hi_heap HI [(A1, 65536%Z)] (debit L cr0 65536) M VM ->
      srealizes RSEGS scfg (mkCfg (mkst R (Z_to_bv 64 0x38c80) M (seg_rom RSEGS)) (model1 VM)) KF.

  (* [comment removed for export] *)
  #[using="uid hw rdraw Hva Hve Hvsp Htid ME Hplen Hsp"] Lemma hiv_facts : forall vals,
    vals_ev vals 3 = auxvp sp0 a0s path envv -> vals_ev vals 4 = rnd sp0 a0s path envv inp ->
    forall i, In i [3%nat; 4%nat] -> (bv_unsigned sp0 <= bv_unsigned (vals_ev vals i))%Z /\ (bv_unsigned (vals_ev vals i) + 2 ^ 20 <= 2 ^ 64)%Z.
  Proof.
    intros vals P3 P4 i Hi.
    destruct (auxvp_u sp0 a0s path envv uid hw rdraw tid regs0 mem0 Hva Hve Hvsp Htid inp mbase entry ME) as [A1 A2].
    destruct (rnd_u sp0 a0s path envv uid hw rdraw tid regs0 mem0 Hva Hve Hvsp Htid inp mbase entry ME) as (R1 & R2 & _ & _).
    destruct Hi as [<-|[<-|[]]]; [rewrite P3 | rewrite P4]; lia.
  Qed.

  (* [comment removed for export] *)
  #[using="Hvsp Hplen Hsp"] Lemma above_sp0_block : forall vals log M,
    vals_ev vals 0 = sp0 -> log_below_b 0 0xfa000 log = true -> above_sp0 M ->
    above_sp0 (mem_denot (ENV vals) M log).
  Proof.
    intros vals log M P0 Hb HA a Ha.
    rewrite (mem_denot_above (ENV vals) M log 0%nat 0xfa000 a Hb); [apply HA; exact Ha | | |];
      cbn [ev ENV]; rewrite ?P0; lia.
  Qed.

  #[using="Type"] Lemma alu_add_w_lit : forall (x : word) k, alu64 ALU_ADD x (Z_to_bv 64 k) = Z_to_bv 64 (bv_unsigned x + k).
  Proof.
    intros x k. rewrite alu_add. unfold v_add. apply bv_eq. rewrite !Z_to_bv_unsigned, !bv_wrap64_mod. rewrite Zplus_mod_idemp_r. reflexivity.
  Qed.

  #[using="HIok uid Hva Hve Hvsp Htid ME Hfile Hpne Hppl Hfs Hplen DL HH0 Hcr0 Hsp Hal"] Theorem drv_open : forall KA KF,
    open_err_k KA -> file_k KF -> KF [] ->
    srealizes RSEGS scfg (mkCfg (mkst regs0 (Z_to_bv 64 0x38c2c) mem0 (seg_rom RSEGS)) model0) (t_alt2 KA KF).
  Proof.
    intros KA KF HKA HKF HKF0.
    pose proof Hsp as Hsp'. pose proof Hal as Hal'.
    pose proof main_regs_ok_d as HR.
    assert (HK : know_ok RSEGS (ENV (vals0 sp0 a0s path envv rdraw tid regs0 inp)) mem0 (kn_d0 ++ [KImg 0xf8c58 0xfa000; KImg 0xc6dd1 0xd8780]))
      by (apply Forall_app; split; [apply main_know_ok_d | apply main_kimg_alloc]).
    set (vals := vals0 sp0 a0s path envv rdraw tid regs0 inp) in *.
    assert (HL : length vals = 38%nat) by (subst vals; unfold vals0; rewrite length_app, junk_vals_length; reflexivity).
    assert (P0 : vals_ev vals 0 = sp0) by reflexivity.
    assert (P1 : vals_ev vals 1 = p0 a0s path envv rdraw inp) by reflexivity.
    assert (P2 : vals_ev vals 2 = p1 a0s path envv rdraw inp) by reflexivity.
    assert (P3 : vals_ev vals 3 = auxvp sp0 a0s path envv) by reflexivity.
    assert (P4 : vals_ev vals 4 = rnd sp0 a0s path envv inp) by reflexivity.
    assert (P5 : vals_ev vals 5 = tid) by reflexivity.
    destruct (main_str sp0 a0s path envv uid hw rdraw tid regs0 mem0 Hva Hve Hvsp Htid inp mbase entry ME 1%nat ltac:(lia)) as (Sr & Slo & Shi & Slen).
    cbn [nth] in Sr, Slo, Shi, Slen.
    assert (HA0 : above_sp0 mem0) by (intros a Ha; reflexivity).
    clearbody vals.
    (* [comment removed for export] *)
    run_block_keep scr0 38%nat.
    assert (HH1 : hi_heap HI [] cr0 M VM0).
    { rewrite EQM. eapply (heap_block scfg L HI HIok sp0 Hsp' DL vals _ []); [exact P0 | intros i nb Hf; discriminate | vm_compute; reflexivity | exact HH0]. }
    assert (HA : above_sp0 M).
    { rewrite EQM. apply above_sp0_block; [exact P0 | vm_compute; reflexivity | exact HA0]. }

    assert (Sr' : rdn RSEGS M (p1 a0s path envv rdraw inp) (length path + 1) = Some (path ++ [Z_to_bv 8 0])).
    { rewrite <- Sr. apply rdn_agree. intros j Hj. pose proof (u64_range (p1 a0s path envv rdraw inp)).
      apply HA. unfold p1 in *. rewrite u_small; lia. }
    clear EQM.
    (* [comment removed for export] *)
    eapply (rz_openat_file RSEGS scfg _ _ _ model0 ECALLW); try apply is_ecall_ECALLW.
    - vm_compute. reflexivity.
    - reflexivity.
    - reflexivity.
    - regv HR (17 : reg). reflexivity.
    - regv HR (10 : reg). apply bv_eq. reflexivity.
    - regv HR (12 : reg). vm_compute. reflexivity.
    - exact Hfs.
    - rewrite m0_fds. rewrite alloc_fd_fds0. apply fd_lookup_fds0_3.
    - split; [exact Hplen|]. split; [apply path_nonul|].
      regv HR (11 : reg). cbn [edenot ev ENV]. rewrite P2. split; [|exact Sr'].
      pose proof (main_str_fits sp0 a0s path envv uid hw rdraw tid regs0 mem0 Hva Hve Hvsp Htid inp mbase entry ME 1%nat ltac:(lia)) as Sfit.
      cbn [nth] in Sfit. unfold p1. unfold TASK_SIZE. lia.
    - exact Hpne.
    - exact Hppl.
    - rewrite m0_fs. exact Hfile.
