  Definition CPpf (w : Z) (a : Z) : Prop :=
    (~ (bv_unsigned sp0 - 208 - 1056 <= a < bv_unsigned sp0 - 208) /\ ~ (0xc6cc0 <= a < 0xc6cc4) /\ ~ (0xc6ce8 <= a < 0xc6cf0) /\ ~ (w <= a < w + 2))%Z.
  Definition SCpf (a : Z) : Prop := (bv_unsigned sp0 - 208 - 1056 <= a < bv_unsigned sp0 - 208)%Z.

  #[using="path fdata Hvsp Hplen Hsp LEN CFG PL B2 CALLS"] Lemma CPpf_outside : forall w a, (0 <= a < 2 ^ 64)%Z -> (0xf9040 <= w <= 0xf943e)%Z -> CPpf w a -> outside (Z_to_bv 64 a) (pf_rs w).
  Proof.
    intros w a Ha Hw (C1 & C2 & C3 & C4). pose proof Hsp as Hsp'.
    cbn [outside pf_rs]. unfold in_rng. rewrite !u_small by lia. repeat split; lia.
  Qed.

