    assert (H1 : lh1_k (t_emit (W 1 (zero_lines 1)) (E (0 + n - 1)%nat))).
    { apply iter1; [unfold E, Ns0DrvE.E; apply t_emit_has_nil|]. rewrite <- En. apply SS_real; lia. }
    unfold lh1_k, Ns0DrvD.lh1_k in H1 |- *. intros fx' vals R M VM A1 PTR OWN LB HLV HR HK HA HBLK HC HPAY HH.
    eapply srz_conseq; [eapply H1; eassumption|].
    unfold E, Ns0DrvE.E. eapply t_eq_trans; [apply t_emit_W_app|].
    replace (zero_lines 1 ++ zero_lines (0 + n - 1)) with (zero_lines n); [apply t_eq_refl|].
    destruct n as [|m]; [lia|]. replace (0 + S m - 1)%nat with m by lia. reflexivity.
  Qed.

